function githubUserQuery({ body }) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Expected a JSON object containing text and channel_id');
  const username = body.text, channelId = body.channel_id;
  if (typeof username !== 'string' || !/^[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(username)) throw new Error('text must be one GitHub username, without whitespace');
  if (typeof channelId !== 'string' || !/^[CDG][A-Z0-9]{2,31}$/.test(channelId)) throw new Error('channel_id must identify a Slack conversation accessible to the selected connection');
  const query = 'query LookupGitHubUser($login: String!) { user(login: $login) { name company location avatarUrl email pullRequests(last: 25) { edges { node { commits(last: 25) { nodes { commit { author { email name } } } } } } } } }';
  return { username, channelId, request: { query, variables: { login: username }, operationName: 'LookupGitHubUser' } };
}

return {json:githubUserQuery({body:$json.body})};

function githubUserProfile({ body, statusCode, bodyEncoding, username }) {
  if (!Number.isInteger(statusCode) || statusCode < 200 || statusCode >= 300) throw new Error('GitHub profile query failed with HTTP ' + statusCode);
  if (bodyEncoding != null || !body || typeof body !== 'object' || Array.isArray(body)) throw new Error('Expected a JSON GitHub GraphQL response');
  if (body.errors != null && (!Array.isArray(body.errors) || body.errors.length)) throw new Error('GitHub returned GraphQL errors; partial profile data is not posted');
  const profile = body.data?.user;
  if (!profile || typeof profile !== 'object' || Array.isArray(profile)) throw new Error('GitHub did not return the requested user');
  for (const key of ['name', 'company', 'location']) if (profile[key] != null && typeof profile[key] !== 'string') throw new Error('Invalid GitHub profile ' + key);
  if (typeof profile.email !== 'string' || typeof profile.avatarUrl !== 'string' || !/^https:\/\/[^\s/?#@<>"'\\]+(?:[/?#][^\s<>"'\\]*)?$/.test(profile.avatarUrl)) throw new Error('Invalid GitHub profile email or avatar URL');
  const edges = profile.pullRequests?.edges;
  if (!Array.isArray(edges) || edges.length > 25) throw new Error('Expected at most 25 pull requests');
  const candidates = profile.email ? [profile.email] : []; let commitsScanned = 0;
  for (const edge of edges) {
    const nodes = edge?.node?.commits?.nodes;
    if (!Array.isArray(nodes) || nodes.length > 25) throw new Error('Expected at most 25 commits per pull request');
    for (const node of nodes) {
      commitsScanned++;
      if (!node?.commit || typeof node.commit !== 'object') throw new Error('Invalid GitHub pull-request commit');
      const author = node.commit.author;
      if (author == null) continue;
      if (typeof author !== 'object' || (author.name != null && typeof author.name !== 'string') || (author.email != null && typeof author.email !== 'string')) throw new Error('Invalid GitHub commit author');
      const matches = typeof author.name === 'string' && ((typeof profile.name === 'string' && profile.name.length > 0 && author.name.includes(profile.name)) || author.name === username);
      if (matches && author.email) candidates.push(author.email);
    }
  }
  const emails = [...new Set(candidates)].filter(email => !/^[^@]+@(?:users\.)?noreply\.github\.com$/i.test(email));
  const escape = text => text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const text = 'Name: ' + (profile.name ?? '') + '\nEmail: ' + emails.join(', ') + '\nCompany: ' + (profile.company ?? '') + '\nLocation: ' + (profile.location ?? '');
  const chunks = []; let chunk = '';
  for (const character of text) { const escaped = escape(character); if (chunk.length + escaped.length > 3800) { chunks.push(chunk); chunk = ''; } chunk += escaped; }
  if (chunk) chunks.push(chunk);
  const title = 'GitHub Details for: ' + username;
  const parts = chunks.map((content, index) => [{ title: chunks.length > 1 ? title + ' (' + (index + 1) + '/' + chunks.length + ')' : title, text: content, fallback: title, mrkdwn_in: [], ...(index === 0 ? { thumb_url: profile.avatarUrl } : {}) }]);
  return { profile, emails, parts, pullRequestsScanned: edges.length, commitsScanned };
}

